def f(value):
    if value: return value*f(value-1)
    return 1
print(f(6),f(value=4))

def f(value): return value+10
def argument():
    print('argument')
    return -3
for target in [abs,f,None,abs]:
    try: print(target(argument()))
    except TypeError: print('not-callable')

class C:
    def __call__(self,value): return value+1
target=C()
for i in range(2):
    print(target(3))
    C.__call__=lambda self,value: value+100

def f(a,b=2): return a,b
try: f()
except TypeError: print('missing')
try: f(1,2,3)
except TypeError: print('extra')
print(f(4))
